                Unit
            }

            is EventSource.SessionLoaded -> {
                buf.putInt(3)
                FfiConverterBoolean.write(value.`signedIn`, buf)
                Unit
            }

            is EventSource.CodeSent -> {
                buf.putInt(4)
                Unit
            }

            is EventSource.CodeAccepted -> {
                buf.putInt(5)
                Unit
            }

            is EventSource.CodeRejected -> {
